#!/usr/bin/env bash
set -euo pipefail
echo "Aplic patch-ul v2: fix detectare header turneu + filtrare dublu"

mkdir -p tenis_scraper
base64 -d > tenis_scraper/tennisexplorer.py << 'B64_TE'

B64_TE

base64 -d > main.py << 'B64_MAIN'

B64_MAIN

python3 -m py_compile tenis_scraper/tennisexplorer.py main.py && echo "COMPILE OK"
echo "Gata. Verifica cu: git status"
